import heapq

def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """ 
    Implements Dijkstra's algorithm to find the shortest path in a weighted directed graph.

    Args:
        graph: Adjacency list representation of the graph.
        start: Starting node.
        end: Destination node.

    Returns:
        A tuple containing the shortest distance and the list of nodes in the path.
    """

    priority_queue = []
    heapq.heappush(priority_queue, (0, start))
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    previous_nodes = {node: None for node in graph}

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                previous_nodes[neighbor] = current_node
                heapq.heappush(priority_queue, (distance, neighbor))

    path = []
    current_node = end
    while current_node is not None:
        path.append(current_node)
        current_node = previous_nodes[current_node]
    path.reverse()

    if distances[end] == float('inf'):
        return (float('inf'), [])

    return (distances[end], path)

def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """ 
    Implements the Bellman-Ford algorithm to find the shortest path in a weighted directed graph.

    Args:
        graph: Adjacency list representation of the graph.
        start: Starting node.
        end: Destination node.

    Returns:
        A tuple containing the shortest distance and the list of nodes in the path.
    """

    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    predecessor = {node: None for node in graph}

    for _ in range(len(graph) - 1):
        for node in graph:
            for neighbor, weight in graph[node]:
                if distances[node] != float('inf') and distances[node] + weight < distances[neighbor]:
                    distances[neighbor] = distances[node] + weight
                    predecessor[neighbor] = node

    path = []
    if distances[end] == float('inf'):
        return (float('inf'), [])

    current_node = end
    while current_node is not None:
        path.append(current_node)
        current_node = predecessor[current_node]

    path.reverse()
    return (distances[end], path)

def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """ 
    Implements the Floyd-Warshall algorithm to find the shortest path in a weighted directed graph.

    Args:
        graph: Adjacency list representation of the graph.
        start: Starting node.
        end: Destination node.

    Returns:
        A tuple containing the shortest distance and the list of nodes in the path.
    """

    # Initialize distance and path matrices
    nodes = list(graph.keys())
    distance = {node: {n: float('inf') for n in nodes} for node in nodes}
    path = {node: {n: None for n in nodes} for node in nodes}

    for node in nodes:
        distance[node][node] = 0

    for node, edges in graph.items():
        for neighbor, weight in edges:
            distance[node][neighbor] = weight
            path[node][neighbor] = node

    # Floyd-Warshall algorithm
    for k in nodes:
        for i in nodes:
            for j in nodes:
                if distance[i][j] > distance[i][k] + distance[k][j]:
                    distance[i][j] = distance[i][k] + distance[k][j]
                    path[i][j] = path[k][j]

    if distance[start][end] == float('inf'):
        return (float('inf'), [])

    # Construct the path from start to end
    shortest_path = []
    current_node = start

    while current_node != end:
        shortest_path.append(current_node)
        if path[current_node][end] is None:  # No path found
            return (float('inf'), [])
        current_node = path[current_node][end]

    shortest_path.append(end)
    return (distance[start][end], shortest_path)
